contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function runTransferCheck(address tokenOwner, uint256 tokens) public {
        // token address is codeless, so the underlying transfer call succeeds
        // at the EVM level but returns no data => decoded success value is false
        require(tokenOwner.code.length == 0);

        bool r = c.transferAnyERC20Token(tokenOwner, tokenOwner, tokens); if (__ESBMC_reverted()) return;

        // P returns the actual transfer result (false here); M always returns true
        assert(!r);
    }

    receive() external payable {}
    fallback() external payable {}
}

